window.TREE={"subject":"Federal Taxation of Individuals","key":"reg_individuals","brand":"Terra Prep","parts":[{"no":1,"name":"Federal Taxation of Individuals","chs":["1-01"],"color":"--fam-eth"}],"chs":[{"key":"1-01","part":1,"no":1,"name":"Federal Taxation of Individuals","nodes":[1,2,3,4,5,6]}],"nodes":[{"no":1,"part":1,"ch":1,"title":"Gross income (inclusions and exclusions)","name":"Gross income (inclusions and exclusions)","vol":10,"q":40,"cs":0,"law":0},{"no":2,"part":1,"ch":1,"title":"Reporting of items from pass-through entities","name":"Reporting of items from pass-through entities","vol":2,"q":10,"cs":0,"law":0},{"no":3,"part":1,"ch":1,"title":"Adjustments and deductions to AGI and taxable income","name":"Adjustments and deductions to AGI and taxable income","vol":7,"q":30,"cs":0,"law":0},{"no":4,"part":1,"ch":1,"title":"Loss limitations","name":"Loss limitations","vol":7,"q":29,"cs":0,"law":0},{"no":5,"part":1,"ch":1,"title":"Filing status","name":"Filing status","vol":7,"q":28,"cs":0,"law":0},{"no":6,"part":1,"ch":1,"title":"Computation of tax and credits","name":"Computation of tax and credits","vol":5,"q":23,"cs":0,"law":0}],"stat":{"parts":1,"chs":1,"nodes":6,"q":160}};
window.QBANK={"1":[{"i":"REGOX-reg_individuals-001","t":"Under section 61(a), gross income means all income from whatever source derived, including compensation for services, gains derived from dealings in property, interest, and dividends.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §61(a)","rat":"§61(a) defines gross income as income from whatever source derived, listing compensation for services, gains from dealings in property, interest, and dividends."},{"i":"REGOX-reg_individuals-002","t":"Under section 61(a)(11), gross income excludes income from the discharge of indebtedness.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §61(a)(11)","rat":"§61(a)(11) lists income from discharge of indebtedness as includible in gross income, not excluded."},{"i":"REGOX-reg_individuals-003","t":"Under section 707(c), a payment to a partner for services, determined without regard to partnership income, is treated as made to a person who is not a partner for purposes of section 61(a).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §707(c)","rat":"A §707(c) guaranteed payment, determined without regard to partnership income, is treated for §61(a) purposes as made to a non-partner and is included in the recipient partner's gross income."},{"i":"REGOX-reg_individuals-004","t":"Under section 707(c), a guaranteed payment to a partner for services is excluded from the partner's gross income under section 61(a).","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §707(c)","rat":"A guaranteed payment is treated as a payment to a non-partner for §61(a) purposes and is therefore included in gross income, not excluded."},{"i":"REGOX-reg_individuals-005","t":"Under section 72(a)(1), gross income includes any amount received as an annuity under an annuity, endowment, or life insurance contract, except as otherwise provided in the chapter.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §72(a)(1)","rat":"§72(a)(1) generally includes amounts received under an annuity contract in gross income."},{"i":"REGOX-reg_individuals-007","t":"Under section 104(a), gross income does not include damages received on account of personal physical injuries or physical sickness, other than punitive damages.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §104(a)(2)","rat":"§104(a)(2) excludes damages for personal physical injury or physical sickness, but expressly carves punitive damages back out of the exclusion (i.e., they are taxable)."},{"i":"REGOX-reg_individuals-008","t":"Under section 104(a)(2), gross income excludes punitive damages received on account of personal physical injury.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §104(a)(2)","rat":"The parenthetical in §104(a)(2) expressly excludes punitive damages from the exclusion, so punitive damages are included in gross income."},{"i":"REGOX-reg_individuals-009","t":"Under section 1001(a), the gain from the sale or other disposition of property is the excess of the amount realized over the adjusted basis provided in section 1011.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1001(a)","rat":"§1001(a) defines gain as the excess of the amount realized over the adjusted basis."},{"i":"REGOX-reg_individuals-010","t":"Under section 1001(a), loss from the sale of property is the excess of the amount realized over the adjusted basis.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1001(a)","rat":"Under §1001(a), loss is the excess of adjusted basis over amount realized; this statement swaps the definitions of gain and loss."},{"i":"REGOX-reg_individuals-011","t":"Under section 1222(3), a gain from the sale or exchange of a capital asset held for more than one year is a long-term capital gain.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1222(3)","rat":"§1222(3) defines long-term capital gain as gain from a capital asset held for more than one year."},{"i":"REGOX-reg_individuals-012","t":"Under section 1222, a gain from the sale of a capital asset held for more than six months is a long-term capital gain.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1222(3)","rat":"The long-term holding-period threshold is more than one year, not six months."},{"i":"REGOX-reg_individuals-013","t":"Under section 1015(a), the basis of property acquired by gift is generally the same as it would be in the hands of the donor, except that for determining loss, the basis may not exceed the property's fair market value at the time of the gift.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1015(a)","rat":"§1015(a) generally carries over the donor's basis to the donee, but caps basis at fair market value at the time of the gift for purposes of determining loss."},{"i":"REGOX-reg_individuals-014","t":"Under section 1015(a), if the donor's adjusted basis exceeds the property's fair market value at the time of the gift, the donee's basis is limited to that fair market value for purposes of determining gain.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1015(a)","rat":"The fair-market-value cap applies only for determining loss, not for determining gain."},{"i":"REGOX-reg_individuals-015","t":"Under section 1014(a)(1), the basis of property acquired from a decedent is generally its fair market value at the date of the decedent's death.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1014(a)(1)","rat":"§1014(a)(1) generally resets (steps up or down) the basis of inherited property to fair market value at the date of death."},{"i":"REGOX-reg_individuals-016","t":"Under section 1014(a), the basis of property acquired from a decedent is the decedent's adjusted basis immediately before death, carried over to the recipient.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1014(a)(1)","rat":"The general rule is a step to date-of-death value, not a carryover basis (subject to exceptions such as §1014(c) for income in respect of a decedent)."},{"i":"REGOX-reg_individuals-017","t":"Under section 1223(9), a person acquiring property from a decedent whose basis is determined under section 1014 is considered to have held the property for more than one year if it is sold within one year after the decedent's death.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1223(9)","rat":"§1223(9) treats inherited property with basis determined under §1014 as held for more than one year, even if disposed of within a year after death."},{"i":"REGOX-reg_individuals-018","t":"Under section 103(a), gross income does not include interest on any state or local bond, except as provided in section 103(b).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §103(a)","rat":"§103(a) excludes interest on state or local bonds from gross income, subject to the exceptions in (b) (e.g., certain private activity bonds)."},{"i":"REGOX-reg_individuals-019","t":"Under section 103(a), gross income excludes interest on all bonds issued by a foreign government.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §103(a)","rat":"The §103(a) exemption covers state or local bonds — bonds issued by a foreign government do not qualify."},{"i":"REGOX-reg_individuals-020","t":"Under section 102(a), gross income does not include the value of property acquired by gift, bequest, devise, or inheritance.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §102(a)","rat":"§102(a) excludes from gross income the value of property acquired by gift, bequest, devise, or inheritance."},{"i":"REGOX-reg_individuals-021","t":"Under section 102(b), income earned from property received as a gift is also excluded from the recipient's gross income.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §102(b)(1)","rat":"§102(b)(1) provides that while the gift property's value is excluded, income later produced by that property is not excluded."},{"i":"REGOX-reg_individuals-022","t":"Under section 102(c)(1), amounts transferred by or for an employer to, or for the benefit of, an employee are not excluded from gross income as a gift.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §102(c)(1)","rat":"§102(c)(1) provides that the gift exclusion does not apply to amounts transferred by an employer to an employee."},{"i":"REGOX-reg_individuals-023","t":"Under section 102(c), amounts transferred by an employer to an employee are excluded from the employee's gross income as a gift.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §102(c)(1)","rat":"Under §102(c)(1), amounts an employer pays an employee are not excluded as a gift."},{"i":"REGOX-reg_individuals-024","t":"Under section 101(a)(1), gross income does not include amounts received under a life insurance contract if paid by reason of the death of the insured, except as otherwise provided in the section.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §101(a)(1)","rat":"§101(a)(1) generally excludes life insurance proceeds paid by reason of the insured's death from gross income."},{"i":"REGOX-reg_individuals-025","t":"Under section 101(a)(2), if a life insurance contract is transferred for valuable consideration, the entire death benefit remains excludable from gross income regardless of the amount paid for the transfer.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §101(a)(2)","rat":"§101(a)(2) caps the exclusion, on a transfer for value, at the consideration paid by the transferee plus premiums later paid (subject to certain exceptions)."},{"i":"REGOX-reg_individuals-026","t":"Under section 691(a)(1), items of gross income in respect of a decedent that were not properly includible for a period ending with or before the decedent's death are included in the gross income of the estate or successor for the taxable year when received.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §691(a)(1)","rat":"§691(a)(1) includes income in respect of a decedent (IRD) in the gross income of the estate or successor for the year received."},{"i":"REGOX-reg_individuals-027","t":"Under section 691(a)(1), items of gross income in respect of a decedent must be included in the decedent's final income tax return covering the period ending with death.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §691(a)(1)","rat":"An IRD item is one that could not properly have been included for the period up to death, and instead is taxed as income of the estate or successor when received."},{"i":"REGOX-reg_individuals-028","t":"Under section 691(a)(3), the right to receive income in respect of a decedent retains, in the hands of the estate or successor, the same character it would have had in the hands of the decedent.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §691(a)(3)","rat":"§691(a)(3) preserves the character IRD would have had if the decedent had lived to receive it."},{"i":"REGOX-reg_individuals-029","t":"Under section 691(a)(3), income in respect of a decedent is always treated as ordinary income regardless of its character in the decedent's hands.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §691(a)(3)","rat":"The character is not automatically converted to ordinary income — it retains the character it would have had in the decedent's hands."},{"i":"REGOX-reg_individuals-030","t":"Under section 691(c)(1)(A), a person who includes an amount in gross income under section 691(a) is allowed a deduction for the portion of the federal estate tax attributable to that item.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §691(c)(1)(A)","rat":"§691(c)(1)(A) allows a deduction for estate tax attributable to IRD to relieve double taxation."},{"i":"REGOX-reg_individuals-031","t":"Under section 691(c), no deduction is allowed for estate tax attributable to income in respect of a decedent.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §691(c)(1)(A)","rat":"§691(c)(1)(A) expressly allows a deduction for the estate tax attributable to the IRD item."},{"i":"REGOX-reg_individuals-032","t":"Under section 691(a)(2), if a right to receive income in respect of a decedent is transferred, the transferor must include the fair market value of the right, plus any excess consideration received, in gross income at the time of the transfer.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §691(a)(2)","rat":"§691(a)(2) includes in the transferor's gross income the fair market value at transfer plus any consideration received in excess of that value, on transfer of a right to IRD."},{"i":"REGMC-reg_individuals-001","t":"Which of the following amounts is included in an individual's gross income under section 61(a)?","c":"A","mc":{"s":"Which of the following amounts is included in an individual's gross income under section 61(a)?","d":"","o":["Interest on a state or local bond excluded under section 103","A fringe benefit received as compensation for services","The value of property acquired by gift","Life insurance proceeds paid by reason of death"],"a":2,"cite":"26 U.S.C. §61(a)(1)","rat":"§61(a)(1) lists compensation for services (including fringe benefits) as an item of gross income; the other choices are excluded under §103, §102, and §101 respectively."}},{"i":"REGMC-reg_individuals-002","t":"Partner P performs services for a partnership and receives a payment computed without regard to partnership income. Under section 707(c), for purposes of gross income under section 61(a), how is the payment treated?","c":"A","mc":{"s":"Partner P performs services for a partnership and receives a payment computed without regard to partnership income. Under section 707(c), for purposes of gross income under section 61(a), how is the payment treated?","d":"","o":["As a distributive share of partnership income under section 702","As a payment made to a person who is not a partner","As a tax-free return of capital","As excluded income under section 102"],"a":2,"cite":"26 U.S.C. §707(c)","rat":"§707(c) treats a guaranteed payment as a payment to a non-partner for §61(a) purposes, so it is included in the recipient partner's gross income."}},{"i":"REGMC-reg_individuals-003","t":"An individual sells a capital asset that was purchased 14 months earlier, recognizing a gain. Under section 1222, this gain is classified as:","c":"A","mc":{"s":"An individual sells a capital asset that was purchased 14 months earlier, recognizing a gain. Under section 1222, this gain is classified as:","d":"","o":["A short-term capital gain because it was held less than 2 years","A long-term capital gain because it was held more than 1 year","Ordinary income under section 61","Section 1231 gain only"],"a":2,"cite":"26 U.S.C. §1222(3)","rat":"§1222(3) defines long-term capital gain as gain from a capital asset held for more than one year."}},{"i":"REGMC-reg_individuals-004","t":"An individual received property as a gift when the donor's adjusted basis was 50,000 and the fair market value at the time of the gift was 30,000. The donee later sells the property for 35,000, resulting in a loss position relative to the donor's basis. Under section 1015(a), which basis governs for purposes of determining loss?","c":"A","mc":{"s":"An individual received property as a gift when the donor's adjusted basis was 50,000 and the fair market value at the time of the gift was 30,000. The donee later sells the property for 35,000, resulting in a loss position relative to the donor's basis. Under section 1015(a), which basis governs for purposes of determining loss?","d":"","o":["50,000 (the donor's adjusted basis)","30,000 (the fair market value at the time of the gift)","35,000 (the amount realized on the sale)","Zero"],"a":2,"cite":"26 U.S.C. §1015(a)","rat":"§1015(a) provides that, for determining loss, if fair market value at the time of the gift is lower than the donor's basis, that fair market value is used as basis."}},{"i":"REGMC-reg_individuals-005","t":"A taxpayer inherits stock from a decedent, takes a basis under section 1014, and sells it 3 months after the decedent's death, recognizing a gain. Under section 1223(9), the gain is treated as:","c":"A","mc":{"s":"A taxpayer inherits stock from a decedent, takes a basis under section 1014, and sells it 3 months after the decedent's death, recognizing a gain. Under section 1223(9), the gain is treated as:","d":"","o":["Short-term because the stock was held less than one year","Long-term because the taxpayer is deemed to have held the stock more than one year","Not a capital gain because the holding period is too short","Ordinary income because inherited property is never a capital asset"],"a":2,"cite":"26 U.S.C. §1223(9)","rat":"§1223(9) treats inherited property with basis determined under §1014 as held for more than one year, even if disposed of within a year after death."}},{"i":"REGMC-reg_individuals-006","t":"Which of the following is excluded from an individual's gross income under the cited Internal Revenue Code section?","c":"A","mc":{"s":"Which of the following is excluded from an individual's gross income under the cited Internal Revenue Code section?","d":"","o":["Interest on a corporate bond","Interest on a state or local bond, under section 103","A cash bonus paid by an employer to an employee, characterized as a gift under section 102(c)","Punitive damages received on account of personal physical injury"],"a":2,"cite":"26 U.S.C. §103(a)","rat":"§103(a) excludes interest on state and local bonds from gross income; the other choices are taxable under §61, §102(c), and §104(a) respectively."}},{"i":"REGMC-reg_individuals-007","t":"An individual inherits property from a decedent under the decedent's will. Under section 102(a), the value of the inherited property is:","c":"A","mc":{"s":"An individual inherits property from a decedent under the decedent's will. Under section 102(a), the value of the inherited property is:","d":"","o":["Included in gross income at fair market value","Excluded from gross income","Included as ordinary income only when later sold","Included only if it exceeds a statutory floor"],"a":2,"cite":"26 U.S.C. §102(a)","rat":"§102(a) excludes from gross income the value of property acquired by gift, bequest, devise, or inheritance."}},{"i":"REGMC-reg_individuals-008","t":"A cash-basis decedent had earned but uncollected wages at the time of death. Under section 691(a)(1)(B), when the employer pays those wages after death, who reports the income?","c":"A","mc":{"s":"A cash-basis decedent had earned but uncollected wages at the time of death. Under section 691(a)(1)(B), when the employer pays those wages after death, who reports the income?","d":"","o":["The decedent, on an amended final return","The person who, by reason of the decedent's death, acquires the right to receive the amount","No one; the amount is permanently excluded from gross income","The employer, as a compensation expense only"],"a":2,"cite":"26 U.S.C. §691(a)(1)(B)","rat":"§691(a)(1)(B) taxes the person who acquired the right to the income by reason of the decedent's death."}},{"i":"REGMC-reg_individuals-009","t":"Under section 691(a)(3), income in respect of a decedent received by the decedent's estate has:","c":"A","mc":{"s":"Under section 691(a)(3), income in respect of a decedent received by the decedent's estate has:","d":"","o":["A new character determined solely by estate tax rules","The same character it would have had if received by the decedent","Always capital gain character","No character; it is disregarded for income tax purposes"],"a":2,"cite":"26 U.S.C. §691(a)(3)","rat":"§691(a)(3) preserves the character income in respect of a decedent would have had if the decedent had lived to receive it."}}],"2":[{"i":"REGOX-reg_individuals-033","t":"Under section 702(a), each partner must take into account separately the partner's distributive share of items such as capital gains and losses, charitable contributions, and other separately stated items.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §702(a)","rat":"§702(a) requires each partner to separately take into account items such as capital gains/losses and charitable contributions."},{"i":"REGOX-reg_individuals-034","t":"Under section 702(a), a partner reports only the net taxable income or loss of the partnership and need not separately state items such as capital gains or charitable contributions.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §702(a)","rat":"§702(a) requires separate statement of these items and does not permit reporting only a net amount."},{"i":"REGOX-reg_individuals-035","t":"Under section 702(b), the character of an item in a partner's distributive share is determined as if the item were realized directly from the source from which the partnership realized it.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §702(b)","rat":"§702(b) provides that the character of an item arising at the partnership level is preserved at the partner level."},{"i":"REGOX-reg_individuals-036","t":"Under section 702(b), all items passed through to a partner are automatically converted to ordinary income regardless of the partnership's character in earning them.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §702(b)","rat":"§702(b) establishes the pass-through character rule; it does not convert items automatically into ordinary income."},{"i":"REGOX-reg_individuals-037","t":"Under section 1366(a)(1), an S corporation shareholder takes into account a pro rata share of the corporation's separately stated items and nonseparately computed income or loss for the shareholder's taxable year in which the corporation's taxable year ends.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1366(a)(1)","rat":"§1366(a)(1) passes S corporation income or loss through to a shareholder's tax year in which the corporation's tax year ends, in proportion to the shareholder's stock."},{"i":"REGOX-reg_individuals-038","t":"Under section 1366(a)(1), an S corporation shareholder reports pass-through items only in the year the corporation actually distributes cash to the shareholder.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1366(a)(1)","rat":"The recognition point is the corporation's year-end, not the date cash is actually distributed."},{"i":"REGOX-reg_individuals-039","t":"Under section 1366(d)(1), the aggregate losses and deductions a shareholder may take into account cannot exceed the sum of the shareholder's adjusted basis in the S corporation's stock and the shareholder's adjusted basis in any indebtedness of the corporation to the shareholder.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1366(d)(1)","rat":"§1366(d)(1) limits the loss deduction to the sum of stock basis and debt basis."},{"i":"REGOX-reg_individuals-040","t":"Under section 1366(d)(1), an S corporation shareholder's loss limitation is based solely on stock basis and never takes into account the shareholder's basis in corporate debt.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1366(d)(1)","rat":"§1366(d)(1) includes both stock basis and the shareholder's basis in corporate debt in the limitation."},{"i":"REGMC-reg_individuals-010","t":"Under section 702(c), for purposes of determining a partner's gross income, the partner must include:","c":"A","mc":{"s":"Under section 702(c), for purposes of determining a partner's gross income, the partner must include:","d":"","o":["Only cash distributions actually received during the year","The partner's distributive share of the partnership's gross income","The partnership's net taxable income only","Nothing, until the partnership interest is sold"],"a":2,"cite":"26 U.S.C. §702(c)","rat":"§702(c) includes the partner's distributive share of partnership gross income in computing the partner's gross income."}},{"i":"REGMC-reg_individuals-011","t":"An S corporation shareholder's stock basis is 5,000, with no basis in corporate debt. The shareholder's pro rata share of an ordinary loss for the year is 8,000. Under section 1366(d)(1)-(2), how much of the loss may the shareholder deduct in the current year?","c":"A","mc":{"s":"An S corporation shareholder's stock basis is 5,000, with no basis in corporate debt. The shareholder's pro rata share of an ordinary loss for the year is 8,000. Under section 1366(d)(1)-(2), how much of the loss may the shareholder deduct in the current year?","d":"","o":["8,000, fully deductible in the current year","5,000, with the remaining 3,000 carried over indefinitely","Zero; the loss is permanently disallowed","5,000, with the excess permanently lost"],"a":2,"cite":"26 U.S.C. §1366(d)(1)-(2)","rat":"§1366(d)(1) limits the loss deduction to the sum of stock and debt basis, and (d)(2) carries the excess forward indefinitely until basis is restored."}}],"3":[{"i":"REGOX-reg_individuals-041","t":"Under section 219(a), an individual is allowed a deduction equal to the amount of the qualified retirement contributions of the individual for the taxable year.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §219(a)","rat":"§219(a) allows a deduction for contributions to an individual retirement account (IRA)."},{"i":"REGOX-reg_individuals-042","t":"Under section 219(b)(1), the deduction allowable under section 219(a) can exceed the compensation includible in the individual's gross income for the taxable year.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §219(b)(1)","rat":"§219(b)(1) limits the deduction to the lesser of the dollar limit or compensation includible in gross income."},{"i":"REGOX-reg_individuals-043","t":"Under section 219(b)(1), the deduction for IRA contributions cannot exceed the lesser of the deductible amount or the compensation includible in the individual's gross income for the taxable year.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §219(b)(1)","rat":"§219(b)(1) sets the deduction limit on a \"lesser of\" basis."},{"i":"REGOX-reg_individuals-044","t":"Under section 223(a), an eligible individual may deduct amounts paid in cash during the taxable year to a health savings account of such individual.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §223(a)","rat":"§223(a) allows a deduction for cash contributions by an eligible individual to a health savings account (HSA)."},{"i":"REGOX-reg_individuals-045","t":"Under section 223(a), a deduction for HSA contributions is allowed even if the individual is not covered under a high deductible health plan.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §223(c)(1)(A)","rat":"Under §223(c)(1)(A), being covered by a high-deductible health plan (HDHP) is required to be an eligible individual."},{"i":"REGOX-reg_individuals-046","t":"Under section 223(d)(1)(A), no contribution will be accepted into a health savings account unless it is in cash, with limited exceptions.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §223(d)(1)(A)","rat":"§223(d)(1)(A) requires HSA contributions to be in cash, with limited exceptions such as rollovers."},{"i":"REGOX-reg_individuals-047","t":"Under section 164(f)(1), an individual is allowed a deduction for one-half of the taxes imposed by section 1401 (other than the tax imposed by section 1401(b)(2)) for the taxable year.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §164(f)(1)","rat":"§164(f)(1) allows a deduction for one-half of self-employment tax as an adjustment to income."},{"i":"REGOX-reg_individuals-048","t":"Under section 164(f)(1), an individual may deduct the full amount of self-employment taxes imposed by section 1401 as an adjustment to income.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §164(f)(1)","rat":"The deductible amount is one-half, not the full amount."},{"i":"REGOX-reg_individuals-049","t":"Under section 213(a), medical expenses paid for the taxpayer, spouse, or a dependent are deductible only to the extent such expenses exceed 7.5 percent of adjusted gross income.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §213(a)","rat":"§213(a) sets the medical expense deduction floor at 7.5% of adjusted gross income."},{"i":"REGOX-reg_individuals-050","t":"Under section 213(a), medical expenses are deductible to the extent they exceed 2 percent of adjusted gross income.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §213(a)","rat":"The correct floor is 7.5%, not 2%."},{"i":"REGOX-reg_individuals-051","t":"Under section 163(h)(1), no deduction is allowed for personal interest paid or accrued by a taxpayer other than a corporation, subject to specified exceptions such as qualified residence interest.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §163(h)(1)-(2)","rat":"§163(h)(1) generally disallows a deduction for personal interest, subject to the exceptions in (h)(2)."},{"i":"REGOX-reg_individuals-052","t":"Under section 163(h), interest paid on a personal credit card balance is fully deductible as itemized interest.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §163(h)(1)","rat":"Credit card interest on personal purchases is personal interest that does not fall within the §163(h)(2) exceptions, so it is nondeductible."},{"i":"REGOX-reg_individuals-053","t":"Under section 163(h)(3)(A), qualified residence interest includes interest on acquisition indebtedness and home equity indebtedness with respect to a qualified residence of the taxpayer, subject to specified limitations.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §163(h)(3)(A)","rat":"§163(h)(3)(A) defines qualified residence interest as interest on acquisition indebtedness and home equity indebtedness."},{"i":"REGOX-reg_individuals-055","t":"Under section 165(h)(5)(A), for taxable years beginning after 2017, a personal casualty loss is deductible even if it is not attributable to a federally declared disaster.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §165(h)(5)(A)","rat":"After 2017, a personal casualty loss not related to a federally declared disaster is generally not deductible."},{"i":"REGOX-reg_individuals-056","t":"Under section 164(a) and section 164(b)(6), state and local real property taxes, personal property taxes, and income taxes are allowed as an itemized deduction, subject to an aggregate dollar limitation for taxable years 2018 through 2025.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §164(a); §164(b)(6)","rat":"§164(b)(6) caps the aggregate deduction for §164(a)(1)-(3) and (b)(5) state and local taxes for tax years 2018 through 2025."},{"i":"REGOX-reg_individuals-057","t":"Under section 164(b)(6), an individual may deduct an unlimited aggregate amount of state and local real property, personal property, and income taxes for taxable years 2018 through 2025.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §164(b)(6)","rat":"§164(b)(6) limits the deduction to an applicable limitation amount; it is not unlimited."},{"i":"REGOX-reg_individuals-058","t":"Under section 199A(a), a taxpayer other than a corporation may generally deduct an amount equal to the lesser of the combined qualified business income amount or 20 percent of taxable income in excess of net capital gain.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §199A(a)","rat":"§199A(a) computes the QBI deduction as the lesser of two amounts."},{"i":"REGOX-reg_individuals-059","t":"Under section 199A(a), the qualified business income deduction is available to C corporations as well as to individuals.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §199A(a)","rat":"§199A(a) expressly limits the deduction to \"a taxpayer other than a corporation.\""},{"i":"REGOX-reg_individuals-060","t":"Under section 199A(c)(1), qualified business income is the net amount of qualified items of income, gain, deduction, and loss with respect to a qualified trade or business of the taxpayer.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §199A(c)(1)","rat":"§199A(c)(1) defines QBI as the net amount of qualified items related to a qualified trade or business."},{"i":"REGOX-reg_individuals-061","t":"Under section 199A(c)(4)(A), reasonable compensation paid to the taxpayer by the taxpayer's qualified trade or business for services rendered is included in qualified business income.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §199A(c)(4)(A)","rat":"§199A(c)(4)(A) excludes reasonable compensation from QBI."},{"i":"REGOX-reg_individuals-062","t":"Under section 199A(d)(1)(B), the trade or business of performing services as an employee is not a qualified trade or business for purposes of the deduction.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §199A(d)(1)(B)","rat":"§199A(d)(1)(B) excludes the performance of services as an employee from a qualified trade or business."},{"i":"REGOX-reg_individuals-063","t":"Under section 199A(c)(3)(B)(i), short-term and long-term capital gains and losses are included as qualified items of income and loss for purposes of computing qualified business income.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §199A(c)(3)(B)(i)","rat":"§199A(c)(3)(B)(i) expressly excludes capital gain or loss items from qualified items."},{"i":"REGOX-reg_individuals-064","t":"Under section 199A(b)(2), for a trade or business subject to the wage and capital limitation, the deductible amount is the lesser of 20 percent of qualified business income or the greater of 50 percent of W-2 wages, or the sum of 25 percent of W-2 wages plus 2.5 percent of the unadjusted basis of qualified property.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §199A(b)(2)","rat":"The §199A(b)(2) formula computes the per-business deduction as the lesser of 20% of QBI or the wage/capital-based limit."},{"i":"REGMC-reg_individuals-012","t":"Under section 164(f)(2), the deduction for one-half of self-employment taxes is treated as attributable to:","c":"A","mc":{"s":"Under section 164(f)(2), the deduction for one-half of self-employment taxes is treated as attributable to:","d":"","o":["A trade or business in which the taxpayer performs services as an employee","A trade or business that does not consist of the performance of services by the taxpayer as an employee","Investment activity described in section 212","Itemized deductions subject to a floor"],"a":2,"cite":"26 U.S.C. §164(f)(2)","rat":"§164(f)(2) attributes the one-half deduction to the trade or business, not to employment."}},{"i":"REGMC-reg_individuals-013","t":"To be an eligible individual for HSA contribution purposes under section 223(c)(1)(A), an individual must:","c":"A","mc":{"s":"To be an eligible individual for HSA contribution purposes under section 223(c)(1)(A), an individual must:","d":"","o":["Be covered under a high deductible health plan and have no disqualifying non-HDHP coverage","Be self-employed","Have adjusted gross income below a specified level","Be enrolled in Medicare"],"a":1,"cite":"26 U.S.C. §223(c)(1)(A)","rat":"§223(c)(1)(A) requires HDHP coverage and the absence of disqualifying other coverage to be an eligible individual."}},{"i":"REGMC-reg_individuals-014","t":"Under section 213(d)(1)(A), which of the following qualifies as medical care for purposes of the medical expense deduction?","c":"A","mc":{"s":"Under section 213(d)(1)(A), which of the following qualifies as medical care for purposes of the medical expense deduction?","d":"","o":["Cosmetic surgery to improve appearance with no functional necessity","Amounts paid for the diagnosis, cure, mitigation, treatment, or prevention of disease","Vitamins purchased for general health maintenance","Life insurance premiums"],"a":2,"cite":"26 U.S.C. §213(d)(1)(A)","rat":"§213(d)(1)(A) defines medical care as amounts paid for the diagnosis, cure, mitigation, treatment, or prevention of disease."}},{"i":"REGMC-reg_individuals-015","t":"Which type of interest is specifically excepted from the disallowance of personal interest under section 163(h)(2)?","c":"A","mc":{"s":"Which type of interest is specifically excepted from the disallowance of personal interest under section 163(h)(2)?","d":"","o":["Interest on a personal auto loan outside any temporary statutory exception","Qualified residence interest","Credit card interest on personal purchases","Interest on a loan used to buy jewelry for personal use"],"a":2,"cite":"26 U.S.C. §163(h)(2)(D)","rat":"§163(h)(2)(D) excludes qualified residence interest from the definition of personal interest."}},{"i":"REGMC-reg_individuals-016","t":"Under section 165(h)(1), a personal casualty loss is allowed only to the extent the loss from each casualty exceeds:","c":"A","mc":{"s":"Under section 165(h)(1), a personal casualty loss is allowed only to the extent the loss from each casualty exceeds:","d":"","o":["A statutory dollar floor per casualty event","100 percent of adjusted gross income","The taxpayer's total itemized deductions for the year","Zero; there is no floor"],"a":1,"cite":"26 U.S.C. §165(h)(1)","rat":"§165(h)(1) allows a casualty loss deduction only for the amount of each casualty that exceeds a set floor per event."}},{"i":"REGMC-reg_individuals-017","t":"Under section 199A(d)(2), a specified service trade or business generally includes which of the following?","c":"A","mc":{"s":"Under section 199A(d)(2), a specified service trade or business generally includes which of the following?","d":"","o":["A manufacturing business","A trade or business involving investing and investment management, trading, or dealing in securities","A retail store","A farming business"],"a":2,"cite":"26 U.S.C. §199A(d)(2)(B)","rat":"§199A(d)(2)(B) names investing, investment management, and trading (among others) as a specified service trade or business."}},{"i":"REGMC-reg_individuals-018","t":"For a taxpayer whose taxable income is below the threshold amount under section 199A(e)(2), the QBI deduction computation for a qualified trade or business is:","c":"A","mc":{"s":"For a taxpayer whose taxable income is below the threshold amount under section 199A(e)(2), the QBI deduction computation for a qualified trade or business is:","d":"","o":["Subject to the full W-2 wage and unadjusted basis limitation of section 199A(b)(2)(B)","Not subject to the wage and capital limitation under section 199A(b)(2)(B)","Automatically zero","Limited to REIT dividends only"],"a":2,"cite":"26 U.S.C. §199A(b)(3)(A)","rat":"§199A(b)(3)(A) applies (b)(2) without regard to subparagraph (B) when taxable income is at or below the threshold amount."}}],"4":[{"i":"REGOX-reg_individuals-065","t":"Under section 1211(b), for a taxpayer other than a corporation, capital losses are allowed only to the extent of capital gains, plus the lower of $3,000 (or $1,500 for a married individual filing a separate return) or the excess of such losses over such gains.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1211(b)","rat":"§1211(b) caps the net capital loss deduction for a noncorporate taxpayer at $3,000 of ordinary income ($1,500 if married filing separately) in excess of capital gains."},{"i":"REGOX-reg_individuals-066","t":"Under section 1211(a), a corporation may deduct up to $3,000 of capital losses in excess of capital gains each year.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1211(a)","rat":"§1211(a) allows a corporation to deduct capital losses only to the extent of capital gains — the $3,000 limit does not apply to corporations."},{"i":"REGOX-reg_individuals-067","t":"Under section 1212(b)(1)(A), the excess of a noncorporate taxpayer's net short-term capital loss over the net long-term capital gain for a taxable year is treated as a short-term capital loss in the succeeding taxable year.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1212(b)(1)(A)","rat":"§1212(b)(1)(A) carries a noncorporate taxpayer's excess net short-term loss forward as a short-term capital loss to the next tax year."},{"i":"REGOX-reg_individuals-068","t":"Under section 1212(b), a noncorporate taxpayer may carry a net capital loss back three years to preceding taxable years.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1212(b)(1)","rat":"A noncorporate taxpayer gets carryforward only, not a three-year carryback — carryback under §1212(a) is available only to corporations."},{"i":"REGOX-reg_individuals-069","t":"Under section 1212(b)(1)(B), the excess of a noncorporate taxpayer's net long-term capital loss over the net short-term capital gain for a taxable year is treated as a long-term capital loss in the succeeding taxable year.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1212(b)(1)(B)","rat":"§1212(b)(1)(B) carries an excess net long-term loss forward as a long-term capital loss to the next tax year."},{"i":"REGOX-reg_individuals-070","t":"Under section 1212(b), a noncorporate taxpayer's capital loss carryforward expires after 5 taxable years.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1212(b)(1)","rat":"There is no expiration on an individual's capital loss carryforward; a limit such as five years applies instead to a corporation's carryforward under §1212(a)."},{"i":"REGOX-reg_individuals-071","t":"Under section 1212(a)(1)(A), a corporation may carry back a net capital loss to each of the 3 taxable years preceding the loss year, subject to specified limitations.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1212(a)(1)(A)","rat":"§1212(a)(1)(A) allows a corporation to carry back a net capital loss to each of the three preceding tax years."},{"i":"REGOX-reg_individuals-072","t":"Under section 469(a)(1), the passive activity loss for the taxable year is not allowed as a deduction for individuals, estates, trusts, closely held C corporations, and personal service corporations.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §469(a)","rat":"§469(a) disallows the passive activity loss deduction for the listed categories of taxpayers."},{"i":"REGOX-reg_individuals-073","t":"Under section 469(a), individuals may fully deduct passive activity losses against nonpassive income without limitation.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §469(a)(1)","rat":"§469(a)(1) generally disallows passive activity losses as a current deduction, allowing only a carryforward."},{"i":"REGOX-reg_individuals-074","t":"Under section 469(c)(1), a passive activity is a trade or business activity in which the taxpayer does not materially participate.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §469(c)(1)","rat":"§469(c)(1) defines a passive activity as a trade or business in which the taxpayer does not materially participate."},{"i":"REGOX-reg_individuals-075","t":"Under section 469(c)(1), a passive activity is any trade or business activity, regardless of the taxpayer's level of participation.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §469(c)(1)","rat":"Passive-activity status turns on the absence of material participation; a statement that it is unrelated to the level of participation is wrong."},{"i":"REGOX-reg_individuals-076","t":"Under section 469(h)(1), a taxpayer is treated as materially participating in an activity only if involved in its operations on a basis that is regular, continuous, and substantial.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §469(h)(1)","rat":"§469(h)(1) requires that material participation be regular, continuous, and substantial."},{"i":"REGOX-reg_individuals-077","t":"Under section 704(d)(1), a partner's distributive share of partnership loss (including capital loss) is allowed only to the extent of the adjusted basis of the partner's interest in the partnership at the end of the partnership year in which such loss occurred.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §704(d)(1)","rat":"§704(d)(1) limits a partner's loss deduction to the partner's adjusted basis in the partnership interest."},{"i":"REGOX-reg_individuals-078","t":"Under section 704(d)(1), a partner may deduct a distributive share of partnership loss without regard to the partner's basis in the partnership interest.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §704(d)(1)","rat":"§704(d)(1) expressly makes basis the limitation on the loss deduction."},{"i":"REGOX-reg_individuals-079","t":"Under section 1366(d)(1), an S corporation shareholder's losses are limited to the sum of the shareholder's adjusted basis in the corporation's stock and the shareholder's adjusted basis in any indebtedness of the corporation to the shareholder.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1366(d)(1)","rat":"§1366(d)(1) limits an S corporation shareholder's loss deduction to the sum of stock basis and debt basis."},{"i":"REGOX-reg_individuals-080","t":"Under section 183(a), if an activity engaged in by an individual is not engaged in for profit, no deduction attributable to such activity is allowed except as provided in section 183.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §183(a)","rat":"§183(a) generally disallows deductions for an activity not engaged in for profit (a hobby)."},{"i":"REGOX-reg_individuals-081","t":"Under section 183(b)(2), deductions attributable to a not-for-profit activity are fully allowed regardless of the activity's gross income.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §183(b)(2)","rat":"§183(b)(2) limits deductions otherwise unrelated to profit motive to the amount by which the activity's gross income exceeds the deductions allowed under (b)(1)."},{"i":"REGOX-reg_individuals-082","t":"Under section 183(d), if the gross income from an activity exceeds the deductions attributable to it for 3 or more of the 5 consecutive taxable years ending with the taxable year, the activity is presumed, absent contrary IRS determination, to be engaged in for profit.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §183(d)","rat":"§183(d) presumes an activity is engaged in for profit if it is profitable in at least 3 of 5 years."},{"i":"REGOX-reg_individuals-083","t":"Under section 1091(a), no deduction is allowed for a loss on the sale of stock or securities if, within a period beginning 30 days before and ending 30 days after the sale, the taxpayer acquires substantially identical stock or securities, unless the taxpayer is a dealer acting in the ordinary course of business.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1091(a)","rat":"§1091(a) disallows the loss deduction through the 61-day wash sale window (30 days before, the day of, and 30 days after the sale)."},{"i":"REGOX-reg_individuals-084","t":"Under section 1091(a), the wash sale rule applies only if substantially identical stock is acquired within 30 days after the sale, not before.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1091(a)","rat":"The §1091(a) window includes both the 30 days before and 30 days after the sale, including purchases in the 30 days before."},{"i":"REGOX-reg_individuals-085","t":"Under section 165(c), an individual's deductible losses are limited to those incurred in a trade or business, in a transaction entered into for profit, or, subject to further limitation, from casualty or theft.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §165(c)","rat":"§165(c) limits an individual's deductible losses to three categories."},{"i":"REGOX-reg_individuals-086","t":"Under section 165(c), a loss on the sale of a personal-use asset is deductible in the same manner as a loss on an investment asset.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §165(c)","rat":"A loss on disposing of a purely personal-use asset — not a business, profit-motivated transaction, or casualty loss — is not deductible under §165(c)."},{"i":"REGOX-reg_individuals-087","t":"Under section 1091(d), the basis of stock or securities acquired in a transaction that results in wash sale disallowance is the basis of the stock sold or disposed of, increased or decreased by the difference between the acquisition price and the sale price.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1091(d)","rat":"§1091(d) provides an adjustment that builds the disallowed wash sale loss into the basis of the newly acquired stock."},{"i":"REGMC-reg_individuals-019","t":"An individual taxpayer (not married filing separately) has 10,000 of capital losses and 4,000 of capital gains for the year, with no other capital transactions. Under section 1211(b), what is the maximum net capital loss deduction against ordinary income for the year?","c":"A","mc":{"s":"An individual taxpayer (not married filing separately) has 10,000 of capital losses and 4,000 of capital gains for the year, with no other capital transactions. Under section 1211(b), what is the maximum net capital loss deduction against ordinary income for the year?","d":"","o":["10,000","6,000","3,000","4,000"],"a":3,"cite":"26 U.S.C. §1211(b)","rat":"§1211(b) caps the deduction for capital losses in excess of capital gains at $3,000 ($1,500 for married filing separately)."}},{"i":"REGMC-reg_individuals-020","t":"Under section 1212(b)(1), an individual's unused net capital loss for the year:","c":"A","mc":{"s":"Under section 1212(b)(1), an individual's unused net capital loss for the year:","d":"","o":["Is permanently lost if not used in the current year","Is carried forward to the succeeding taxable year, retaining its short-term or long-term character","Is carried back three years to preceding taxable years","Converts entirely to ordinary loss in future years"],"a":2,"cite":"26 U.S.C. §1212(b)(1)","rat":"§1212(b)(1) carries an individual's excess net capital loss forward to the next tax year, preserving its character."}},{"i":"REGMC-reg_individuals-021","t":"An individual materially participates in a partnership's trade or business and has sufficient basis under section 704(d) to absorb a distributive share of ordinary loss. Because the individual materially participates, the loss is:","c":"A","mc":{"s":"An individual materially participates in a partnership's trade or business and has sufficient basis under section 704(d) to absorb a distributive share of ordinary loss. Because the individual materially participates, the loss is:","d":"","o":["Automatically classified as a passive activity loss under section 469(c)(1)","Not a passive activity under section 469(c)(1) because of material participation, so it may offset nonpassive income (subject to basis and other limits)","Limited to 3,000 under section 1211","Disallowed entirely under section 183"],"a":2,"cite":"26 U.S.C. §469(c)(1)","rat":"§469(c)(1) excludes an activity with material participation from the definition of a passive activity."}},{"i":"REGMC-reg_individuals-022","t":"Under section 704(d)(2), a partnership loss disallowed for lack of basis in the current year is:","c":"A","mc":{"s":"Under section 704(d)(2), a partnership loss disallowed for lack of basis in the current year is:","d":"","o":["Permanently disallowed","Allowed as a deduction at the end of the partnership year in which the excess is repaid to the partnership (i.e., when basis is restored)","Automatically converted to a capital loss","Allowed only against passive income"],"a":2,"cite":"26 U.S.C. §704(d)(2)","rat":"§704(d)(2) allows a loss disallowed for lack of basis to be deducted in the year basis is restored."}},{"i":"REGMC-reg_individuals-023","t":"An individual sells stock at a loss on November 1 and repurchases substantially identical stock on November 20 (within 30 days after the sale). Under section 1091(a), the loss is:","c":"A","mc":{"s":"An individual sells stock at a loss on November 1 and repurchases substantially identical stock on November 20 (within 30 days after the sale). Under section 1091(a), the loss is:","d":"","o":["Fully deductible in the year of sale","Disallowed","Deductible up to 3,000","Deductible only against capital gains"],"a":2,"cite":"26 U.S.C. §1091(a)","rat":"§1091(a) disallows the loss deduction when substantially identical securities are reacquired within 30 days before or after the sale."}},{"i":"REGMC-reg_individuals-024","t":"An individual breeds horses without a profit motive, and the activity does not benefit from the presumption in section 183(d). Under section 183(b), deductions attributable to the activity are limited to:","c":"A","mc":{"s":"An individual breeds horses without a profit motive, and the activity does not benefit from the presumption in section 183(d). Under section 183(b), deductions attributable to the activity are limited to:","d":"","o":["Zero","The amount of gross income from the activity in excess of deductions otherwise allowable without regard to profit motive","The taxpayer's total itemized deductions for the year","An unlimited amount, the same as a for-profit business"],"a":2,"cite":"26 U.S.C. §183(b)(2)","rat":"§183(b)(2) limits deductions otherwise unrelated to profit motive to the amount by which the activity's gross income exceeds the §183(b)(1) deductions."}}],"5":[{"i":"REGOX-reg_individuals-088","t":"Under section 1(a), a married individual, as defined in section 7703, who makes a joint return with a spouse under section 6013 is taxed under the rate schedule for married individuals filing jointly and surviving spouses.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1(a)","rat":"§1(a) sets the rate schedule applicable to married individuals filing jointly and §2(a) surviving spouses."},{"i":"REGOX-reg_individuals-089","t":"Under section 2(a)(1), an individual qualifies as a surviving spouse for any taxable year following the death of the spouse, with no time limit.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §2(a)(1)(A)","rat":"§2(a)(1)(A) limits surviving spouse status to cases where the spouse died in one of the taxpayer's two immediately preceding tax years."},{"i":"REGOX-reg_individuals-090","t":"Under section 2(b)(1), an individual generally qualifies as head of household if not married at the close of the taxable year and maintains a household that is the principal place of abode of a qualifying child or other dependent for more than half the taxable year.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §2(b)(1)","rat":"§2(b)(1) requires head-of-household status to be unmarried and to maintain a household with a dependent."},{"i":"REGOX-reg_individuals-091","t":"Under section 7703(a)(1), the determination of whether an individual is married is generally made as of the first day of the taxable year.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §7703(a)(1)","rat":"Marital status is determined as of the close of the tax year (or date of death if the spouse died during the year), not the first day of the tax year."},{"i":"REGOX-reg_individuals-092","t":"Under section 7703(b), a married individual who lives apart from a spouse for the last 6 months of the taxable year, maintains as the individual's home a household that is the principal place of abode of a qualifying child for more than half the year, and furnishes over half the cost of maintaining that household, may be treated as not married.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §7703(b)","rat":"§7703(b) sets the requirements for treating certain separated married individuals as unmarried."},{"i":"REGOX-reg_individuals-093","t":"Under section 7703(a)(2), an individual who is legally separated from a spouse under a decree of divorce or of separate maintenance is still considered married for tax purposes.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §7703(a)(2)","rat":"§7703(a)(2) provides that an individual legally separated under a decree of divorce or separate maintenance is not considered married."},{"i":"REGOX-reg_individuals-094","t":"Under section 2(a)(2)(A), a taxpayer who has remarried at any time before the close of the taxable year shall not be considered a surviving spouse for that year.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §2(a)(2)(A)","rat":"§2(a)(2)(A) denies surviving spouse status if the taxpayer has remarried."},{"i":"REGOX-reg_individuals-095","t":"Under section 152(a), the term dependent means a qualifying child or a qualifying relative.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §152(a)","rat":"§152(a) defines a dependent as either a qualifying child or a qualifying relative."},{"i":"REGOX-reg_individuals-096","t":"Under section 152(c)(2), a qualifying child may bear any relationship to the taxpayer, including an unrelated person living in the household.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §152(c)(2)","rat":"The relationship test for a qualifying child is limited to a child (or descendant) or sibling (or half-sibling) and their descendants — an unrelated household member does not qualify."},{"i":"REGOX-reg_individuals-097","t":"Under section 152(d)(1)(B), a qualifying relative's gross income for the calendar year in which the taxpayer's taxable year begins must be less than the exemption amount defined in section 151(d).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §152(d)(1)(B)","rat":"§152(d)(1)(B) sets the gross income limit for a qualifying relative."},{"i":"REGOX-reg_individuals-098","t":"Under section 152(d)(1)(C), a qualifying relative need not receive any support from the taxpayer.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §152(d)(1)(C)","rat":"§152(d)(1)(C) requires the taxpayer to provide more than half of the person's support for the year."},{"i":"REGOX-reg_individuals-099","t":"Under section 152(d)(2)(H), an individual who has the same principal place of abode as the taxpayer and is a member of the taxpayer's household for the taxable year may satisfy the relationship test for a qualifying relative.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §152(d)(2)(H)","rat":"§152(d)(2)(H) lets the relationship test be satisfied by being a member of the household for the year even without a family relationship."},{"i":"REGOX-reg_individuals-100","t":"Under section 152(c)(1)(B), a qualifying child must have the same principal place of abode as the taxpayer for more than one-half of the taxable year.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §152(c)(1)(B)","rat":"§152(c)(1)(B) sets the qualifying child residency test at more than half the tax year."},{"i":"REGOX-reg_individuals-101","t":"Under section 152(c)(3)(A), a full-time student qualifying child must not have attained age 19 by the close of the calendar year, with no higher age permitted even for students.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §152(c)(3)(A)","rat":"§152(c)(3)(A)(ii) relaxes the age test to under 24 for a full-time student."},{"i":"REGOX-reg_individuals-102","t":"Under section 152(e)(1)-(2), a child of divorced or separated parents may be treated as the qualifying child or qualifying relative of the noncustodial parent if the custodial parent signs a written declaration releasing the claim to the exemption for the year.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §152(e)(1)-(2)","rat":"§152(e) lets a noncustodial parent claim dependent status through a written declaration releasing the exemption by the custodial parent."},{"i":"REGOX-reg_individuals-103","t":"A married couple who files a joint return under section 6013 is taxed under section 1(a) using the rate schedule for married individuals filing jointly and surviving spouses.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1(a)","rat":"§1(a) sets the rate schedule for married couples filing jointly."},{"i":"REGOX-reg_individuals-104","t":"A married couple filing a joint return under section 6013 is taxed under section 1(c), the rate schedule for unmarried individuals.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1(c)","rat":"§1(c) is the rate schedule for unmarried individuals (not a surviving spouse or head of household); married couples filing jointly are subject to §1(a)."},{"i":"REGOX-reg_individuals-105","t":"An individual whose spouse died during the current taxable year and who has not remarried is treated as married as of the date of death for that taxable year under section 7703(a)(1), permitting a joint return.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §7703(a)(1)","rat":"§7703(a)(1) determines marital status as of the date of death if a spouse died during the tax year."},{"i":"REGOX-reg_individuals-106","t":"An unmarried individual who is not a surviving spouse and maintains a household that is the principal place of abode of a qualifying child for more than half the year may compute tax under the head of household schedule described in section 1(b).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1(b); §2(b)","rat":"The head-of-household rate schedule applies when the requirements of §1(b) and §2(b) are met."},{"i":"REGOX-reg_individuals-107","t":"An individual may claim head of household status under section 2(b)(1)(A) merely by claiming any dependent on the tax return, without regard to where the dependent lives.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §2(b)(1)(A)","rat":"§2(b)(1)(A) generally requires a qualifying child or dependent to live with the taxpayer for more than half the tax year (an exception for parents is in (B))."},{"i":"REGOX-reg_individuals-108","t":"A married individual who does not make a joint return with a spouse is taxed under section 1(d), the schedule for married individuals filing separately, unless treated as not married under section 7703(b).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1(d); §7703(b)","rat":"§1(d) is the rate schedule for married individuals filing separately; a taxpayer meeting the §7703(b) requirements may be treated as unmarried."},{"i":"REGOX-reg_individuals-109","t":"An individual whose spouse died 3 taxable years ago may still use the surviving spouse rate schedule under section 2(a) for the current year, provided a dependent child lives with the taxpayer.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §2(a)(1)(A)","rat":"Surviving spouse status applies only for the two tax years immediately following the year of the spouse's death, so it does not apply if the spouse died three years ago."},{"i":"REGMC-reg_individuals-025","t":"Under section 7703(a)(1), the determination of whether an individual is married is generally made as of:","c":"A","mc":{"s":"Under section 7703(a)(1), the determination of whether an individual is married is generally made as of:","d":"","o":["The first day of the taxable year","The close of the taxable year (or the date of death, if the spouse dies during the year)","The date the tax return is filed","The date of the marriage ceremony, regardless of when in the year it occurred"],"a":2,"cite":"26 U.S.C. §7703(a)(1)","rat":"§7703(a)(1) determines marital status as of the close of the tax year (or the date of the spouse's death)."}},{"i":"REGMC-reg_individuals-026","t":"Which of the following is required for an unmarried individual to qualify as head of household under section 2(b)(1)(A)?","c":"A","mc":{"s":"Which of the following is required for an unmarried individual to qualify as head of household under section 2(b)(1)(A)?","d":"","o":["The individual must maintain a household that is the principal place of abode of a qualifying child or dependent for more than half the year","The individual must have no dependents","The individual must be over a specified age","The individual must have been married at some point during the year"],"a":1,"cite":"26 U.S.C. §2(b)(1)(A)","rat":"§2(b)(1)(A) requires maintaining a household and living with a dependent."}},{"i":"REGMC-reg_individuals-027","t":"Which relationship satisfies the qualifying relative relationship test under section 152(d)(2)?","c":"A","mc":{"s":"Which relationship satisfies the qualifying relative relationship test under section 152(d)(2)?","d":"","o":["A cousin living in a separate household","A brother-in-law","A friend with no family relationship who lives in a separate household","A former spouse who is not a household member"],"a":2,"cite":"26 U.S.C. §152(d)(2)(G)","rat":"§152(d)(2)(G) includes a brother-in-law or sister-in-law relationship in the qualifying-relative relationship test."}},{"i":"REGMC-reg_individuals-028","t":"Under section 152(c)(1)(D), a qualifying child must not have provided:","c":"A","mc":{"s":"Under section 152(c)(1)(D), a qualifying child must not have provided:","d":"","o":["Any support at all during the calendar year","Over one-half of the individual's own support for the calendar year","More than 10 percent of household expenses","Support to any other person"],"a":2,"cite":"26 U.S.C. §152(c)(1)(D)","rat":"§152(c)(1)(D) requires that the qualifying child not have provided more than half of their own support."}},{"i":"REGMC-reg_individuals-029","t":"Taxpayer's spouse died during Year 1. Taxpayer did not remarry and maintains a household for a dependent child who qualifies under section 152. For Year 2 and Year 3 (the two taxable years immediately following the year of death), which rate schedule may the taxpayer use under sections 2(a) and 1(a)?","c":"A","mc":{"s":"Taxpayer's spouse died during Year 1. Taxpayer did not remarry and maintains a household for a dependent child who qualifies under section 152. For Year 2 and Year 3 (the two taxable years immediately following the year of death), which rate schedule may the taxpayer use under sections 2(a) and 1(a)?","d":"","o":["Single, under section 1(c)","Head of household, under section 1(b)","Surviving spouse (joint-return rate schedule), under section 1(a)","Married filing separately, under section 1(d)"],"a":3,"cite":"26 U.S.C. §2(a)(1); §1(a)","rat":"Meeting the requirements of §2(a)(1) entitles the taxpayer to the §1(a) rate schedule for the two tax years following the spouse's death."}},{"i":"REGMC-reg_individuals-030","t":"An individual is legally separated from her spouse under a decree of separate maintenance as of the close of the taxable year and does not otherwise qualify as head of household. Under section 7703(a)(2) and section 2(c), how is she treated for purposes of section 1?","c":"A","mc":{"s":"An individual is legally separated from her spouse under a decree of separate maintenance as of the close of the taxable year and does not otherwise qualify as head of household. Under section 7703(a)(2) and section 2(c), how is she treated for purposes of section 1?","d":"","o":["As a married individual filing separately, because she is still legally married","As not married, because of the legal separation decree, so section 1(c) applies if no other status applies","As a surviving spouse under section 2(a)","As a head of household automatically, regardless of other requirements"],"a":2,"cite":"26 U.S.C. §7703(a)(2)","rat":"§7703(a)(2) provides that a person legally separated under a decree of divorce or separate maintenance is not considered married."}}],"6":[{"i":"REGOX-reg_individuals-110","t":"Under section 6654(d)(1)(B), the required annual payment is the lesser of 90 percent of the tax shown on the return for the taxable year or 100 percent of the tax shown on the return for the preceding taxable year (subject to a higher percentage for certain higher-income taxpayers).","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §6654(d)(1)(B)","rat":"§6654(d)(1)(B) sets the required annual payment at the lesser of 90% of the current year's tax or 100% of the prior year's tax."},{"i":"REGOX-reg_individuals-111","t":"Under section 6654(d)(1)(B), the required annual payment is the greater of 90 percent of the current year's tax or 100 percent of the preceding year's tax.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §6654(d)(1)(B)","rat":"The correct standard is the \"lesser of,\" not the \"greater of.\""},{"i":"REGOX-reg_individuals-112","t":"Under section 6654(d)(1)(C)(i), if the adjusted gross income shown on the individual's return for the preceding taxable year exceeds $150,000, the 100 percent prior-year safe harbor percentage is increased to 110 percent.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §6654(d)(1)(C)(i)","rat":"§6654(d)(1)(C)(i) raises the safe harbor percentage to 110% if the prior year's AGI exceeded $150,000."},{"i":"REGOX-reg_individuals-113","t":"Under section 6654(d)(1)(C), the 110 percent prior-year safe harbor threshold applies to all taxpayers regardless of income level.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §6654(d)(1)(C)(i)","rat":"The 110% threshold applies only to taxpayers whose prior-year AGI exceeded the stated amount."},{"i":"REGOX-reg_individuals-114","t":"Under section 6654(c)(1), there are 4 required installments of estimated tax for each taxable year.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §6654(c)(1)","rat":"§6654(c)(1) requires four estimated tax installments per year."},{"i":"REGOX-reg_individuals-115","t":"Under section 6654(c)(1), there are 12 required installments of estimated tax for each taxable year, due monthly.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §6654(c)(1)","rat":"The number of installments is four, not twelve."},{"i":"REGOX-reg_individuals-116","t":"Under section 6654(e)(1), no addition to tax is imposed if the tax shown on the return for the taxable year, reduced by the credit allowable under section 31, is less than $1,000.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §6654(e)(1)","rat":"§6654(e)(1) imposes no penalty if the tax due after withholding is less than $1,000."},{"i":"REGOX-reg_individuals-117","t":"Under section 6654(e)(1), the addition to tax applies regardless of how small the underpayment is, with no minimum tax threshold exception.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §6654(e)(1)","rat":"§6654(e)(1) expressly provides a de minimis exception when the tax due is less than $1,000."},{"i":"REGOX-reg_individuals-118","t":"Under section 6654(e)(2), no addition to tax is imposed if the individual had no tax liability for the preceding taxable year, that year was a taxable year of 12 months, and the individual was a citizen or resident of the United States throughout that year.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §6654(e)(2)","rat":"§6654(e)(2) sets the requirements for the prior-year no-tax-liability exception."},{"i":"REGOX-reg_individuals-119","t":"Under section 1(a) through 1(d), an individual's federal income tax liability before credits is computed by applying the rate schedule that corresponds to the individual's filing status to taxable income.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1(a)-(d)","rat":"§1(a)-(d) set different rate schedules by filing status."},{"i":"REGOX-reg_individuals-120","t":"Under section 1411(a)(1), an individual is subject to a tax equal to 3.8 percent of the lesser of net investment income for the taxable year or the excess of modified adjusted gross income over the threshold amount.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1411(a)(1)","rat":"§1411(a)(1) imposes the 3.8% net investment income tax on the lesser of two amounts."},{"i":"REGOX-reg_individuals-121","t":"Under section 1411(a)(1), the 3.8 percent tax applies to the greater of net investment income or the excess of modified adjusted gross income over the threshold amount.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1411(a)(1)","rat":"The §1411(a)(1) tax base is the \"lesser of\" the two amounts, not the \"greater of.\""},{"i":"REGOX-reg_individuals-122","t":"Under section 1411(b), the threshold amount is $250,000 in the case of a joint return or a surviving spouse, and $200,000 in the case of an individual not otherwise specified.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1411(b)","rat":"§1411(b) sets threshold amounts that vary by filing status."},{"i":"REGOX-reg_individuals-123","t":"Under section 1411(b)(2), a married taxpayer filing a separate return has a threshold amount equal to the full $250,000 threshold used for joint filers.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1411(b)(2)","rat":"§1411(b)(2) sets the threshold for a married-filing-separately taxpayer at half the joint-filing threshold."},{"i":"REGOX-reg_individuals-124","t":"Under section 1411(c)(1), net investment income includes gross income from interest, dividends, annuities, royalties, and rents (other than such income derived in the ordinary course of certain active trades or businesses), reduced by properly allocable deductions.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1411(c)(1)","rat":"§1411(c)(1) defines the components of net investment income and the deduction of related expenses."},{"i":"REGOX-reg_individuals-125","t":"Under section 1411(c), net investment income includes wages and self-employment income that is subject to self-employment tax under section 1401.","ox":"X","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1411(c)(6)","rat":"§1411(c)(6) excludes from net investment income amounts subject to self-employment tax under §1401(b)."},{"i":"REGOX-reg_individuals-126","t":"Under section 1411(e)(1), the tax imposed by section 1411 does not apply to a nonresident alien.","ox":"O","y":null,"e":"US CPA REG","qn":null,"c":"A","cite":"26 U.S.C. §1411(e)(1)","rat":"§1411(e)(1) expressly provides that the net investment income tax does not apply to nonresident aliens."},{"i":"REGMC-reg_individuals-031","t":"Under section 6654(c)(2), the due date for the second required installment of estimated tax for a calendar-year individual is:","c":"A","mc":{"s":"Under section 6654(c)(2), the due date for the second required installment of estimated tax for a calendar-year individual is:","d":"","o":["April 15","June 15","September 15","January 15 of the following taxable year"],"a":2,"cite":"26 U.S.C. §6654(c)(2)","rat":"§6654(c)(2) sets the second estimated tax installment deadline as June 15."}},{"i":"REGMC-reg_individuals-032","t":"A calendar-year individual's prior-year adjusted gross income exceeded the threshold in section 6654(d)(1)(C)(i). To use the prior-year safe harbor, the individual generally must pay estimated tax equal to at least:","c":"A","mc":{"s":"A calendar-year individual's prior-year adjusted gross income exceeded the threshold in section 6654(d)(1)(C)(i). To use the prior-year safe harbor, the individual generally must pay estimated tax equal to at least:","d":"","o":["90 percent of the current year's tax","100 percent of the prior year's tax","110 percent of the prior year's tax","66 2/3 percent of the current year's tax"],"a":3,"cite":"26 U.S.C. §6654(d)(1)(C)(i)","rat":"§6654(d)(1)(C)(i) raises the safe harbor percentage to 110% for a higher-income taxpayer based on prior-year AGI."}},{"i":"REGMC-reg_individuals-033","t":"Under section 6654(e)(2), no addition to tax for underpayment of estimated tax is imposed if:","c":"A","mc":{"s":"Under section 6654(e)(2), no addition to tax for underpayment of estimated tax is imposed if:","d":"","o":["The taxpayer requested an extension of time to file","The taxpayer had no tax liability for the preceding full 12-month taxable year and was a citizen or resident of the United States throughout that year","The taxpayer is filing a return for the first time","The taxpayer's income is entirely from wages"],"a":2,"cite":"26 U.S.C. §6654(e)(2)","rat":"§6654(e)(2) waives the penalty if there was no tax liability in the prior year and the citizenship/residency requirements are met."}},{"i":"REGMC-reg_individuals-034","t":"A single individual (not a surviving spouse or head of household) has modified adjusted gross income of 220,000 and net investment income of 30,000 for the year. Under sections 1411(a)(1) and 1411(b)(3), the additional 3.8 percent tax applies to:","c":"A","mc":{"s":"A single individual (not a surviving spouse or head of household) has modified adjusted gross income of 220,000 and net investment income of 30,000 for the year. Under sections 1411(a)(1) and 1411(b)(3), the additional 3.8 percent tax applies to:","d":"","o":["30,000, the full amount of net investment income","20,000, the lesser of net investment income or the excess of MAGI over the 200,000 threshold","220,000, the entire modified AGI","Zero, because MAGI is below the joint-return threshold"],"a":2,"cite":"26 U.S.C. §1411(a)(1), (b)(3)","rat":"Because the MAGI excess ($220,000 - $200,000 = $20,000) is less than net investment income ($30,000), $20,000 is the tax base."}},{"i":"REGMC-reg_individuals-035","t":"Under section 1(a) through 1(d), which of the following correctly pairs a filing status with its governing rate schedule provision?","c":"A","mc":{"s":"Under section 1(a) through 1(d), which of the following correctly pairs a filing status with its governing rate schedule provision?","d":"","o":["Head of household — section 1(c)","Married filing jointly — section 1(a)","Married filing separately — section 1(b)","Single (unmarried, not head of household or surviving spouse) — section 1(d)"],"a":2,"cite":"26 U.S.C. §1(a)","rat":"§1(a) sets the rate schedule for married filing jointly and surviving spouses; head of household is (b), unmarried individuals are (c), and married filing separately is (d)."}},{"i":"REGMC-reg_individuals-036","t":"Under section 1411(c)(4), when a taxpayer disposes of an interest in a partnership or S corporation, gain from the disposition is taken into account as net investment income only to the extent of:","c":"A","mc":{"s":"Under section 1411(c)(4), when a taxpayer disposes of an interest in a partnership or S corporation, gain from the disposition is taken into account as net investment income only to the extent of:","d":"","o":["The entire gain recognized on the disposition","The net gain that would be taken into account by the transferor if all property of the entity were sold at fair market value immediately before the disposition","Any amount, at the taxpayer's election","Zero; partnership and S corporation interest dispositions are always excluded"],"a":2,"cite":"26 U.S.C. §1411(c)(4)(A)","rat":"§1411(c)(4)(A) limits the portion of gain on a disposition of a partnership or S corporation interest that is treated as net investment income to the net gain that would be recognized if the entity sold all its assets at fair market value."}}]};
window.PAIRS=[{"n":1,"s":0.67,"o":{"i":"REGOX-reg_individuals-011","t":"Under section 1222(3), a gain from the sale or exchange of a capital asset held for more than one year is a long-term capital gain.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-012","t":"Under section 1222, a gain from the sale of a capital asset held for more than six months is a long-term capital gain.","y":null,"e":"US CPA REG"}},{"n":1,"s":0.643,"o":{"i":"REGOX-reg_individuals-009","t":"Under section 1001(a), the gain from the sale or other disposition of property is the excess of the amount realized over the adjusted basis provided in section 1011.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-010","t":"Under section 1001(a), loss from the sale of property is the excess of the amount realized over the adjusted basis.","y":null,"e":"US CPA REG"}},{"n":1,"s":0.614,"o":{"i":"REGOX-reg_individuals-022","t":"Under section 102(c)(1), amounts transferred by or for an employer to, or for the benefit of, an employee are not excluded from gross income as a gift.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-023","t":"Under section 102(c), amounts transferred by an employer to an employee are excluded from the employee's gross income as a gift.","y":null,"e":"US CPA REG"}},{"n":1,"s":0.608,"o":{"i":"REGOX-reg_individuals-007","t":"Under section 104(a), gross income does not include damages received on account of personal physical injuries or physical sickness, other than punitive damages.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-008","t":"Under section 104(a)(2), gross income excludes punitive damages received on account of personal physical injury.","y":null,"e":"US CPA REG"}},{"n":2,"s":0.413,"o":{"i":"REGOX-reg_individuals-033","t":"Under section 702(a), each partner must take into account separately the partner's distributive share of items such as capital gains and losses, charitable contributions, and other separately stated items.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-034","t":"Under section 702(a), a partner reports only the net taxable income or loss of the partnership and need not separately state items such as capital gains or charitable contributions.","y":null,"e":"US CPA REG"}},{"n":2,"s":0.365,"o":{"i":"REGOX-reg_individuals-037","t":"Under section 1366(a)(1), an S corporation shareholder takes into account a pro rata share of the corporation's separately stated items and nonseparately computed income or loss for the shareholder's taxable year in which the corporation's taxable year ends.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-040","t":"Under section 1366(d)(1), an S corporation shareholder's loss limitation is based solely on stock basis and never takes into account the shareholder's basis in corporate debt.","y":null,"e":"US CPA REG"}},{"n":3,"s":0.623,"o":{"i":"REGOX-reg_individuals-043","t":"Under section 219(b)(1), the deduction for IRA contributions cannot exceed the lesser of the deductible amount or the compensation includible in the individual's gross income for the taxable year.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-042","t":"Under section 219(b)(1), the deduction allowable under section 219(a) can exceed the compensation includible in the individual's gross income for the taxable year.","y":null,"e":"US CPA REG"}},{"n":3,"s":0.547,"o":{"i":"REGOX-reg_individuals-049","t":"Under section 213(a), medical expenses paid for the taxpayer, spouse, or a dependent are deductible only to the extent such expenses exceed 7.5 percent of adjusted gross income.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-050","t":"Under section 213(a), medical expenses are deductible to the extent they exceed 2 percent of adjusted gross income.","y":null,"e":"US CPA REG"}},{"n":3,"s":0.536,"o":{"i":"REGOX-reg_individuals-056","t":"Under section 164(a) and section 164(b)(6), state and local real property taxes, personal property taxes, and income taxes are allowed as an itemized deduction, subject to an aggregate dollar limitation for taxable years 2018 through 2025.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-057","t":"Under section 164(b)(6), an individual may deduct an unlimited aggregate amount of state and local real property, personal property, and income taxes for taxable years 2018 through 2025.","y":null,"e":"US CPA REG"}},{"n":3,"s":0.335,"o":{"i":"REGOX-reg_individuals-041","t":"Under section 219(a), an individual is allowed a deduction equal to the amount of the qualified retirement contributions of the individual for the taxable year.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-045","t":"Under section 223(a), a deduction for HSA contributions is allowed even if the individual is not covered under a high deductible health plan.","y":null,"e":"US CPA REG"}},{"n":4,"s":0.534,"o":{"i":"REGOX-reg_individuals-074","t":"Under section 469(c)(1), a passive activity is a trade or business activity in which the taxpayer does not materially participate.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-075","t":"Under section 469(c)(1), a passive activity is any trade or business activity, regardless of the taxpayer's level of participation.","y":null,"e":"US CPA REG"}},{"n":4,"s":0.39,"o":{"i":"REGOX-reg_individuals-071","t":"Under section 1212(a)(1)(A), a corporation may carry back a net capital loss to each of the 3 taxable years preceding the loss year, subject to specified limitations.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-068","t":"Under section 1212(b), a noncorporate taxpayer may carry a net capital loss back three years to preceding taxable years.","y":null,"e":"US CPA REG"}},{"n":4,"s":0.362,"o":{"i":"REGOX-reg_individuals-077","t":"Under section 704(d)(1), a partner's distributive share of partnership loss (including capital loss) is allowed only to the extent of the adjusted basis of the partner's interest in the partnership at the end of the partnership year in which such loss occurred.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-078","t":"Under section 704(d)(1), a partner may deduct a distributive share of partnership loss without regard to the partner's basis in the partnership interest.","y":null,"e":"US CPA REG"}},{"n":4,"s":0.338,"o":{"i":"REGOX-reg_individuals-083","t":"Under section 1091(a), no deduction is allowed for a loss on the sale of stock or securities if, within a period beginning 30 days before and ending 30 days after the sale, the taxpayer acquires substantially identical stock or securities, unless the taxpayer is a dealer acting in the ordinary course of business.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-084","t":"Under section 1091(a), the wash sale rule applies only if substantially identical stock is acquired within 30 days after the sale, not before.","y":null,"e":"US CPA REG"}},{"n":5,"s":0.585,"o":{"i":"REGOX-reg_individuals-103","t":"A married couple who files a joint return under section 6013 is taxed under section 1(a) using the rate schedule for married individuals filing jointly and surviving spouses.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-104","t":"A married couple filing a joint return under section 6013 is taxed under section 1(c), the rate schedule for unmarried individuals.","y":null,"e":"US CPA REG"}},{"n":5,"s":0.301,"o":{"i":"REGOX-reg_individuals-095","t":"Under section 152(a), the term dependent means a qualifying child or a qualifying relative.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-098","t":"Under section 152(d)(1)(C), a qualifying relative need not receive any support from the taxpayer.","y":null,"e":"US CPA REG"}},{"n":6,"s":0.792,"o":{"i":"REGOX-reg_individuals-114","t":"Under section 6654(c)(1), there are 4 required installments of estimated tax for each taxable year.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-115","t":"Under section 6654(c)(1), there are 12 required installments of estimated tax for each taxable year, due monthly.","y":null,"e":"US CPA REG"}},{"n":6,"s":0.574,"o":{"i":"REGOX-reg_individuals-120","t":"Under section 1411(a)(1), an individual is subject to a tax equal to 3.8 percent of the lesser of net investment income for the taxable year or the excess of modified adjusted gross income over the threshold amount.","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-121","t":"Under section 1411(a)(1), the 3.8 percent tax applies to the greater of net investment income or the excess of modified adjusted gross income over the threshold amount.","y":null,"e":"US CPA REG"}},{"n":6,"s":0.441,"o":{"i":"REGOX-reg_individuals-110","t":"Under section 6654(d)(1)(B), the required annual payment is the lesser of 90 percent of the tax shown on the return for the taxable year or 100 percent of the tax shown on the return for the preceding taxable year (subject to a higher percentage for certain higher-income taxpayers).","y":null,"e":"US CPA REG"},"x":{"i":"REGOX-reg_individuals-111","t":"Under section 6654(d)(1)(B), the required annual payment is the greater of 90 percent of the current year's tax or 100 percent of the preceding year's tax.","y":null,"e":"US CPA REG"}}];
